public class Product
{
    public int Id { get; set; } // convention -> primary key
    [Required, MaxLength(100)]
    public string Name { get; set; }
    public decimal Price { get; set; }
    public int CategoryId { get; set; } // convention -> foreign key
    public Category Category { get; set; } // navigation property
}

public class AppDbContext : DbContext
{
    public DbSet<Product> Products { get; set; }

    protected override void OnModelCreating(ModelBuilder mb) // Fluent API
    {
        mb.Entity<Product>().Property(p => p.Price).HasPrecision(18, 2);
        mb.Entity<Product>().HasIndex(p => p.Name);
        mb.Entity<Product>().HasOne(p => p.Category).WithMany(c => c.Products)
            .HasForeignKey(p => p.CategoryId);
    }
}

