// Eager - ONE query with JOINs
var orders = db.Orders
    .Include(o => o.Customer)
    .Include(o => o.Items).ThenInclude(i => i.Product)
    .ToList();

// Lazy - a SEPARATE query fires on first access
var order = db.Orders.First();
Console.WriteLine(order.Customer.Name); // query fires HERE

// Explicit - you decide when
db.Entry(order).Reference(o => o.Customer).Load();
db.Entry(order).Collection(o => o.Items).Query().Where(i => i.Qty > 5).Load();

// The N+1 trap (lazy loading in a loop)
var allOrders = db.Orders.ToList();               // 1 query
foreach (var o in allOrders) Print(o.Customer.Name); // +1 query PER ORDER

// Fix 1: split query to avoid cartesian explosion
db.Orders.Include(o => o.Items).Include(o => o.Payments).AsSplitQuery().ToList();

// Fix 2 (best): projection - no entity loading at all
var data = db.Orders.Select(o => new { o.Id, CustomerName = o.Customer.Name }).ToList();

var product = db.Products.First();     // tracked; snapshot stored
product.Price = 500;                   // no DB call yet - state becomes Modified
db.SaveChanges();                      // UPDATE Products SET Price = 500 WHERE Id = ...

// Read-only queries: skip tracking entirely
var products = db.Products.AsNoTracking().ToList();  // no snapshots - faster, less memory
db.ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking; // global default

// Long-running batch loop: release accumulated tracked entities
foreach (var batch in batches)
{
    // ... process batch, SaveChanges()
    db.ChangeTracker.Clear();
}

// True bulk operation - bypasses tracking, one SQL statement
await db.Orders.Where(o => o.Date < cutoff).ExecuteDeleteAsync();

// Read-only, projected, paginated, translatable
var page = await db.Orders
    .AsNoTracking()
    .Where(o => o.Status == OrderStatus.Shipped)      // SARGable - translates to an index seek
    .OrderBy(o => o.Id)
    .Where(o => o.Id > lastSeenId)                     // keyset pagination for deep pages
    .Take(50)
    .Select(o => new { o.Id, o.Total, CustomerName = o.Customer.Name }) // projection, not full entities
    .ToListAsync();

// Cartesian explosion fix for multi-collection Include
db.Orders.Include(o => o.Items).Include(o => o.Payments).AsSplitQuery().ToList();

// Bulk write bypassing per-row SaveChanges
await db.Orders.Where(o => o.Date < cutoff).ExecuteDeleteAsync();

// Raw SQL / stored proc through EF, when EF's SQL is poor
var orders = db.Orders.FromSqlRaw("EXEC GetOrderSummary @p0", customerId).ToList();

